modules.Guide:
--[[
	Guide — the "how to build one" text behind each skin category's Guide button: what the model
	is called, what its pieces are called, where their pivots go, and the category's own traps.
	The socket and alias lists are read from Slots so they can never disagree with the checks;
	the rest is written by hand from the game's skin rules (SailMe-Arena1
	docs/notes/shipyard/skin-publishing-guide.md, tooling/assets-place.md). Keep it short and
	keep it true: when a check or the game changes, change the line here too.
]]

local Slots = require(script.Parent.Slots)

local Guide = {}

-- every ship skin, whatever its slot (short: one rule per line)
local SHIP_COMMON = {
	"Name: <Theme><Slot>, e.g. DiscoOctoDoor. No spaces or dots.",
	"Tag the model with its theme.",
	"Pieces: MeshParts, direct children, named after their socket.",
	"Each piece: a mesh + a SurfaceAppearance or texture.",
	"Pivot = where it sits on the ship. Check with Preview.",
	"Don't replace rig parts (seat, candle, Billy's face).",
}

-- per slot: what this kind of skin needs beyond the common rules
local SHIP = {
	Wheel = {
		"Needs a FaceRig (Setup → Add face).",
		"RotationPart is required: the face follows it.",
		"Tune the face in Setup: move / turn / size, part colours.",
	},
	Lantern = {
		"Needs a CandleRig light (Setup → Add light & VFX).",
		"Setup: light colour, intensity, range, each effect's colours.",
		"Glass can be see-through.",
	},
	Cannon = {
		"Make all three mouths: CloseMouth = loaded, OpenMouth + Tongue = empty.",
		"Check each: Setup → Mouth Loaded / Unloaded.",
	},
	Anchor = {
		"Mounts on the capstan rig: judge the pivots on the ship.",
		"A missing hand or cap keeps the ship's own.",
		"Check Setup → Anchor Down / Up / Trick (hands out).",
	},
	Window = {
		"BasePart = frame, CoverPart = shutter. Each has its own pivot.",
		"Check the cover in Setup → Window Closed / Open.",
	},
	Door = {
		"Both leaves: LeftDoor and RightDoor.",
		"Glass: LeftGlass / RightGlass, same pivot as its leaf.",
		"Leaves face opposite ways. Wrong one? Turn 180°.",
	},
	Bell = {
		"BasePart = frame, RotationPart = bell, TonguePart = clapper.",
	},
	Board = {
		"Double-sided: optional (Setup).",
		"Needs a BoardTextPlane (Setup → Add name text).",
		"Names are 3–12 characters. Test with Try → 12.",
	},
	Sail = {
		"One MeshPart with one SurfaceAppearance. Folder: Sailes.",
	},
	Harpoon = {
		"No harpoon skins yet.",
	},
	Stove = {
		"Shipyard only (the Arena has no stove yet).",
	},
}

local TOOL_COMMON = {
	"Name: <Tool>_<Name>. No spaces or dots.",
	"One MeshPart, tagged SwordSkin / FlintlockSkin / BucketSkin.",
}

local TOOL = {
	Sword = { "HiltEnd: \"+Z\" or \"-Z\" = the handle end." },
	Flintlock = { "SkinPitch / Yaw / Roll if it sits sideways." },
	Bucket = { "WaterDiameter + WaterRim size the water." },
}

-- { title, sections = { { heading, lines } } } for a skin's category
function Guide.forSkin(skin)
	if skin.kind == "ship" then
		local def = Slots.SHIP[skin.slot] or {}
		local names = {}
		if def.sockets then
			table.insert(names, (#def.sockets == 1 and "Socket: " or "Pieces: ") .. table.concat(def.sockets, ", ") .. ".")
		end
		table.insert(names, "Folder: workspace." .. (def.folder or skin.slot))
		return {
			title = skin.slot .. " skins",
			sections = {
				{ heading = "Names", lines = names },
				{ heading = skin.slot, lines = SHIP[skin.slot] or {} },
				{ heading = "Every ship skin", lines = SHIP_COMMON },
			},
		}
	end
	local def = Slots.TOOL[skin.slot] or {}
	local attrs = {}
	for k, t in pairs(def.required or {}) do table.insert(attrs, k .. " (" .. t .. ", required)") end
	for k, t in pairs(def.optional or {}) do table.insert(attrs, k .. " (" .. t .. ", optional)") end
	table.sort(attrs)
	local lines = table.clone(TOOL[skin.slot] or {})
	if #attrs > 0 then table.insert(lines, 1, "Attributes: " .. table.concat(attrs, ", ") .. ".") end
	return {
		title = skin.slot .. " skins",
		sections = {
			{ heading = skin.slot, lines = lines },
			{ heading = "Every tool skin", lines = TOOL_COMMON },
		},
	}
end

return Guide

modules.Slots:
--[[
	Slots — what each skin type looks like in the Assets place and what the game
	reads for it. Socket names and aliases were taken from the game's SkinService
	(Arena src/server + Shipyard places/shipyard/server) and from the 85 rows that
	were already catalogued on 2026-09-28 (every Assets piece matched to its row by
	mesh id). Matching is case-insensitive, so only real renames need an alias.
]]

local Slots = {}

-- SHIP SKINS -> ReplicatedStorage.SkinCatalog.<Slot> + ServerStorage.SkinAppearances.<Slot>
-- folder     : workspace.<folder> in the Assets place
-- sockets    : the names SkinService mounts on (a piece's `socket`)
-- aliases    : lower-case piece name -> socket
-- reference  : a model in the folder whose pieces show where the sockets are
--              (its parts' pivots are the socket frames); used to check pivots
-- extras     : "candle" (lantern light/VFX), "face" (wheel face), "text" (board name)
-- rig        : written into every row (Anchor: pieces mount on the template rig)
Slots.SHIP = {
	Anchor = {
		folder = "Anchor",
		sockets = { "BasePart", "RotationPart", "LeftHand", "RightHand", "CenterPart" },
		aliases = { cappart = "CenterPart", cap = "CenterPart", knob = "CenterPart", center = "CenterPart" },
		reference = "AnchorDefault",
		rig = "template",
	},
	Wheel = {
		folder = "Wheel",
		sockets = { "BasePart", "RotationPart" },
		aliases = { base = "BasePart", wheel = "RotationPart", wheelpart = "RotationPart" },
		extras = "face",
	},
	Cannon = {
		folder = "Cannon",
		sockets = { "BasePart", "RotationPart", "OpenMouth", "CloseMouth", "Tongue", "Aim" },
		aliases = { aimpart = "Aim", base = "BasePart" },
		reference = "CannonDefault",
	},
	Lantern = {
		folder = "Lantern",
		sockets = { "Handle", "Base", "Glass", "Legs" },
		aliases = { basepart = "Base", hangingpart = "Handle" },
		reference = "LanternDefaultFinal",
		extras = "candle",
	},
	Harpoon = {
		folder = "Harpoon",
		sockets = { "BasePart", "LowerRotationPart", "UpperRotationPart" },
	},
	Door = {
		folder = "Door",
		sockets = { "LeftDoor", "RightDoor" },
		-- a leaf's glass is its own (transparent) mesh, mounted on that leaf's socket
		aliases = { leftglass = "LeftDoor", rightglass = "RightDoor" },
		pair = true, -- a double door: warn when one leaf is missing
	},
	Window = {
		folder = "Window",
		sockets = { "BasePart", "CoverPart" },
		aliases = { frame = "BasePart", cover = "CoverPart" },
	},
	Board = {
		folder = "Board",
		sockets = { "Board" },
		extras = "text",
	},
	Bell = {
		folder = "Bell",
		sockets = { "BasePart", "RotationPart", "TonguePart" },
		aliases = { rotationalpart = "RotationPart" },
		reference = "bellTemplate",
	},
	Stove = {
		folder = "Stove",
		sockets = { "Stove" },
	},
	Sail = {
		folder = "Sailes",
		texture = true, -- a MeshPart carrying one SurfaceAppearance -> SkinAppearances.Sail.<Key>.Surface
	},
}

-- the order slots are listed in the panel
Slots.ORDER = { "Wheel", "Lantern", "Cannon", "Anchor", "Window", "Door", "Bell", "Board", "Sail", "Harpoon", "Stove" }

-- models in a slot folder that are references, rigs or parked parts, never skins
Slots.NOT_A_SKIN_TAGS = { defaultTest = true, Main = true }
function Slots.isReferenceName(name)
	local l = name:lower()
	return l:find("template", 1, true) ~= nil or l:find("default", 1, true) ~= nil
end

-- TOOL SKINS -> ReplicatedStorage.ToolSkins.<Tool>.<Key> (a Package)
-- tag        : CollectionService tag on the designer's model (PVP&NPC ASSETS place)
-- required   : mount attributes ToolSkinMount needs on the model
-- optional   : mount attributes with a default
Slots.TOOL = {
	Sword = {
		tag = "SwordSkin",
		required = { HiltEnd = "string" },
		optional = { SkinOffset = "Vector3" },
		check = function(model)
			local h = model:GetAttribute("HiltEnd")
			if h ~= nil and h ~= "+Z" and h ~= "-Z" then
				return "HiltEnd must be \"+Z\" or \"-Z\" (it is " .. tostring(h) .. ")"
			end
			return nil
		end,
	},
	Flintlock = {
		tag = "FlintlockSkin",
		required = {},
		optional = { SkinPitch = "number", SkinYaw = "number", SkinRoll = "number", SkinOffset = "Vector3" },
	},
	Bucket = {
		tag = "BucketSkin",
		required = { WaterDiameter = "number", WaterRim = "number" },
		optional = { WaterOffset = "Vector3", SkinPitch = "number", SkinYaw = "number", SkinRoll = "number", SkinOffset = "Vector3" },
	},
}
Slots.TOOL_ORDER = { "Sword", "Flintlock", "Bucket" }

-- the game's tiers, as the catalogue and the ToolSkins attributes spell them
Slots.TIERS = { common = "Common", rare = "Rare", epic = "Epic", legendary = "Legendary" }

-- the socket a piece name maps to, or nil
function Slots.socketFor(def, pieceName)
	if #def.sockets == 1 then return def.sockets[1] end
	local l = pieceName:lower():gsub("%s+$", "")
	for _, s in ipairs(def.sockets) do
		if s:lower() == l then return s end
	end
	return def.aliases and def.aliases[l] or nil
end

return Slots
